import (
	"errors"
	"fmt"
)

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("division by zero") // a new error with a message
	}
	return a / b, nil // nil: no error
}

func counter() func() int {
	n := 0
	return func() int { n++; return n } // closure: keeps its own n between calls
}

func main() {
	if q, err := divide(1, 0); err != nil {
		fmt.Println("error:", err) // error: division by zero
	} else {
		fmt.Println(q)
	}
	next := counter()
	next()
	fmt.Println(next()) // 2
}

