type Shape interface {
	Area() float64
}

type Circle struct{ R float64 }
type Square struct{ S float64 }

func (c Circle) Area() float64  { return math.Pi * c.R * c.R }
func (s Square) Area() float64  { return s.S * s.S }
func (s Square) String() string { return fmt.Sprintf("square(%g)", s.S) }

func describe(v any) string {
	switch x := v.(type) {
	case fmt.Stringer:
		return x.String()
	case Shape:
		return fmt.Sprintf("shape with area %.1f", x.Area())
	default:
		return "unknown"
	}
}

func main() {
	for _, s := range []Shape{Circle{1}, Square{2}} {
		fmt.Println(describe(s)) // shape with area 3.1, then square(2)
	}
}

