import (
	"errors"
	"fmt"
)

func safeDiv(a, b int) (q int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r) // set named result
		}
	}()
	return a / b, nil
}

func main() {
	for i := range 3 {
		defer fmt.Print(i, " ") // runs at return: 2 1 0
	}
	_, err := safeDiv(1, 0)
	fmt.Println(err)                       // recovered: runtime error: integer divide by zero
	fmt.Println(errors.Unwrap(err) == nil) // true
}

