import "fmt"

// generate returns a receive-only channel and closes it when done.
func generate(n int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for i := range n {
			out <- i * i
		}
	}()
	return out
}

func main() {
	sum := 0
	for v := range generate(5) { // ends when out is closed
		sum += v
	}
	fmt.Println(sum) // 30

	buf := make(chan string, 2)
	buf <- "a"
	buf <- "b" // doesn't block: buffer has room
	close(buf)
	v, ok := <-buf
	fmt.Println(v, ok, len(buf)) // a true 1
}

