import (
	"fmt"
	"time"
)

func slowQuery(d time.Duration) <-chan string {
	ch := make(chan string, 1) // buffered: sender never leaks
	go func() {
		time.Sleep(d)
		ch <- "result"
	}()
	return ch
}

func main() {
	select {
	case r := <-slowQuery(50 * time.Millisecond):
		fmt.Println(r)
	case <-time.After(10 * time.Millisecond):
		fmt.Println("timed out") // this one wins
	}

	events := make(chan int)
	select {
	case e := <-events:
		fmt.Println(e)
	default:
		fmt.Println("no event ready") // non-blocking
	}
}

