type Stats struct {
	mu   sync.Mutex
	hits map[string]int
}

func (s *Stats) Record(page string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.hits[page]++
}

func main() {
	s := &Stats{hits: make(map[string]int)}
	var wg sync.WaitGroup
	for i := range 100 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			s.Record([]string{"home", "about"}[i%2])
		}()
	}
	wg.Wait()
	fmt.Println(s.hits) // map[about:50 home:50]
}

