import (
	"context"
	"fmt"
	"time"
)

func work(ctx context.Context, steps int) error {
	for i := range steps {
		select {
		case <-ctx.Done():
			return fmt.Errorf("stopped at step %d: %w", i, ctx.Err())
		case <-time.After(20 * time.Millisecond):
			// one unit of work done
		}
	}
	return nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	err := work(ctx, 10)
	fmt.Println(err) // stopped at step 2: context deadline exceeded
}

