// countingReader wraps any io.Reader and overrides only Read.
type countingReader struct {
	io.Reader // embedded interface
	n         int
}

func (c *countingReader) Read(p []byte) (int, error) {
	n, err := c.Reader.Read(p) // call the wrapped reader explicitly
	c.n += n
	return n, err
}

func main() {
	cr := &countingReader{Reader: strings.NewReader("hello, embedding")}
	data, _ := io.ReadAll(cr)
	fmt.Println(string(data), cr.n) // hello, embedding 16
}

