func Map[T, U any](xs []T, f func(T) U) []U {
	out := make([]U, 0, len(xs))
	for _, x := range xs {
		out = append(out, f(x))
	}
	return out
}

func MaxOf[T cmp.Ordered](first T, rest ...T) T {
	m := first
	for _, v := range rest {
		m = max(m, v)
	}
	return m
}

func main() {
	fmt.Println(Map([]int{1, 2, 3}, strconv.Itoa)) // [1 2 3] as []string
	fmt.Println(MaxOf(3, 9, 4), MaxOf("b", "a"))   // 9 b
}

