import (
	"context"
	"fmt"
)

// stage applies f to each value from in; it owns and closes out.
func stage(ctx context.Context, in <-chan int, f func(int) int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case out <- f(n):
			case <-ctx.Done():
				return // consumer gave up: exit instead of leaking
			}
		}
	}()
	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel() // unblocks every stage if we stop early

	src := make(chan int, 4)
	for i := 1; i <= 4; i++ {
		src <- i
	}
	close(src)

	squares := stage(ctx, src, func(n int) int { return n * n })
	for v := range stage(ctx, squares, func(n int) int { return n + 1 }) {
		fmt.Print(v, " ") // 2 5 10 17
	}
}

