package counter

import (
	"sync"
	"sync/atomic"
	"testing"
)

func TestCounter(t *testing.T) {
	var racy int
	var safe atomic.Int64
	var wg sync.WaitGroup
	for range 50 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			racy++      // WARNING: DATA RACE reported here
			safe.Add(1) // atomic: fine
