	"sync"
	"sync/atomic"
)

func main() {
	fmt.Println("CPUs:", runtime.NumCPU(), "Ps:", runtime.GOMAXPROCS(0))

	var wg sync.WaitGroup
	var done atomic.Int64
	for range 10_000 { // 10k goroutines, a handful of threads
		wg.Add(1)
		go func() {
			defer wg.Done()
			runtime.Gosched() // yield the P to another runnable G
			done.Add(1)
		}()
	}
	fmt.Println("goroutines now:", runtime.NumGoroutine() > 1)
	wg.Wait()
	fmt.Println("finished:", done.Load()) // finished: 10000
}

