import (
	"fmt"
	"sync/atomic"
)

var (
	data  string
	ready atomic.Bool // plain bool here would be a data race
)

func producer() {
	data = "hello"    // (1) ordinary write
	ready.Store(true) // (2) atomic store publishes (1)
}

func main() {
	go producer()
	for !ready.Load() { // (3) observes (2), so (1) happens before (4)
	}
	fmt.Println(data) // (4) guaranteed: hello
}

