	p := newPoint()         // inlined here: &point{...} does not escape
	fmt.Println(p.x, sum()) // args escape: converted to interface

	buf := make([]byte, 0, 32) // constant size, does not escape
	buf = strconv.AppendInt(buf, 42, 10)
	println(string(buf)) // 42
}

