import (
	"fmt"
	"testing"
)

type MyErr struct{}

func (*MyErr) Error() string { return "boom" }

func mayFail(fail bool) error {
	var p *MyErr // typed nil pointer
	if fail {
		p = &MyErr{}
	}
	return p // WRONG: interface holds (*MyErr, nil)
}

var sink any

func main() {
	fmt.Println(mayFail(false) != nil) // true — the typed-nil trap

	n := 1000
	allocs := testing.AllocsPerRun(100, func() { sink = n }) // int is boxed
	fmt.Println("allocs per boxing:", allocs)                // 1

	defer func() { fmt.Println("recovered:", recover()) }()
	var a, b any = []int{1}, []int{1}
	fmt.Println(a == b) // panics: comparing uncomparable type []int
}

package main

import (
	"fmt"
	"unsafe"
)

type padded struct {
	a bool  // 1 byte + 7 padding
	b int64 // 8
	c bool  // 1 byte + 7 padding
}

type packed struct {
	b    int64
	a, c bool // 2 bytes + 6 padding
}

func bytesToString(b []byte) string {
	return unsafe.String(unsafe.SliceData(b), len(b)) // zero-copy: b must not change
}

func main() {
	fmt.Println(unsafe.Sizeof(padded{}), unsafe.Sizeof(packed{})) // 24 16
	fmt.Println(unsafe.Offsetof(packed{}.c))                      // 9
	fmt.Println(bytesToString([]byte("no copy")))                 // no copy
}
